import {demoStar,routeGrades} from './diagnose-access-grades.mjs';
import {BOARD_CELLS,validateFootprints,rawTerrain} from '../board-terrain.js';
const summaries=[];for(const cell of BOARD_CELLS){const b=demoStar(cell.q,cell.r);try{validateFootprints(b);}catch{continue;}const r=routeGrades(b);if(r.warnings.length)continue;summaries.push({q:cell.q,r:cell.r,padded:Math.max(...r.rows.map(x=>Math.max(x.grade,x.crossGrade))),raw:Math.max(...r.rows.filter(x=>x.kind!=='courtyard').map(x=>Math.max(x.rawGrade,x.rawCrossGrade))),failed:r.rows.filter(x=>Math.max(x.grade,x.crossGrade)>.25).length});}console.log(JSON.stringify(summaries.sort((a,b)=>a.padded-b.padded).slice(0,12),null,2));console.log('lowest unpadded gradients',JSON.stringify(summaries.sort((a,b)=>a.raw-b.raw).slice(0,8),null,2));
